add_action( 'woocommerce_admin_order_item_headers', 'perfectpixel_order_item_field_header' );
add_action( 'woocommerce_admin_order_item_values', 'perfectpixel_order_item_field_value', 10, 3 );
add_action( 'woocommerce_before_save_order_item', 'perfectpixel_order_item_field_save' );

function perfectpixel_order_item_field_header() {
	echo '<th class="perfectpixel-item-field">' . esc_html( '{{order_item_field_label}}' ) . '</th>';
}

function perfectpixel_order_item_field_value( $product, $item, $item_id ) {
	if ( ! $item instanceof WC_Order_Item_Product ) {
		echo '<td></td>';
		return;
	}
	$value = $item->get_meta( '_perfectpixel_item_field' );
	echo '<td class="perfectpixel-item-field" width="1%"><div class="view">' . esc_html( $value ) . '</div><div class="edit" style="display:none"><input type="text" name="perfectpixel_item_field[' . absint( $item_id ) . ']" value="' . esc_attr( $value ) . '" style="width:6em"></div></td>';
}

function perfectpixel_order_item_field_save( $item ) {
	if ( ! current_user_can( 'edit_shop_orders' ) ) {
		return;
	}
	// Items are saved via ajax (serialized form in $_POST['items']) or with the whole order form.
	$data = $_POST;
	if ( isset( $_POST['items'] ) && is_string( $_POST['items'] ) ) {
		parse_str( wp_unslash( $_POST['items'] ), $data );
	}
	if ( isset( $data['perfectpixel_item_field'][ $item->get_id() ] ) ) {
		$item->update_meta_data( '_perfectpixel_item_field', sanitize_text_field( wp_unslash( $data['perfectpixel_item_field'][ $item->get_id() ] ) ) );
	}
}
